CREATE DATABASE themepark;
USE themepark;
CREATE TABLE THEMEPARK (
  PARK_CODE VARCHAR(10) PRIMARY KEY,
  PARK_NAME VARCHAR(35) NOT NULL,
  PARK_CITY VARCHAR(50) NOT NULL,
  PARK_COUNTRY CHAR(2) NOT NULL
);
CREATE INDEX EMP_LNAME_INDEX ON EMPLOYEE(EMP_LNAME(8));
ALTER TABLE ATTRACTION MODIFY ATTRACT_CAPACITY NUMERIC(4);
DROP TABLE SALES_LINE, SALES, HOURS, ATTRACTION, TICKET, EMPLOYEE, THEMEPARK;

UPDATE ATTRACTION SET ATTRACT_AGE = 14;  -- thiếu WHERE: sửa mọi hàng
SET AUTOCOMMIT = 0;
ROLLBACK;
DELETE FROM PARK_COPY WHERE PARK_CODE = 'RL1';
INSERT INTO EMP_COPY SELECT * FROM EMPLOYEE;

SELECT TICKET_NO, ROUND(TICKET_PRICE * 0.1, 2) AS Discount FROM TICKET;
SELECT * FROM EMPLOYEE WHERE EMP_FNAME LIKE '%n_';
SELECT * FROM SECTION WHERE SECTIONNO BETWEEN 2713 AND 2717;

SELECT * FROM attraction INNER JOIN themepark
  ON attraction.park_code = themepark.park_code;
SELECT * FROM attraction NATURAL JOIN themepark;
SELECT * FROM themepark LEFT JOIN attraction
  ON attraction.park_code = themepark.park_code;

SELECT * FROM ticket
WHERE ticket_price = (SELECT MIN(ticket_price) FROM ticket);
SELECT * FROM employee
WHERE emp_num IN (SELECT DISTINCT emp_num FROM hours WHERE hour_rate > 6);

CREATE VIEW display_employee AS
SELECT * FROM employee NATURAL JOIN themepark;
SELECT * FROM display_employee;

DELIMITER //
CREATE PROCEDURE get_average_quantity(OUT average INT)
BEGIN
  SELECT AVG(line_qty) INTO average FROM sales_line;
END //
DELIMITER ;
CALL get_average_quantity(@average);
SELECT @average, sales_line.* FROM sales_line WHERE line_qty < @average;
